import{_ as a,o as e,c as o,a2 as s}from"./chunks/framework.C4u7U0Dw.js";const c=JSON.parse('{"title":"课外阅读：一章看懂 AI 工作系统","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/课外阅读 一章看懂 AI 工作系统.md","filePath":"bluebook/课外阅读 一章看懂 AI 工作系统.md"}'),n={name:"bluebook/课外阅读 一章看懂 AI 工作系统.md"};function d(l,t,i,r,p,h){return e(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="课外阅读-一章看懂-ai-工作系统" tabindex="-1">课外阅读：一章看懂 AI 工作系统 <a class="header-anchor" href="#课外阅读-一章看懂-ai-工作系统" aria-label="Permalink to &quot;课外阅读：一章看懂 AI 工作系统&quot;">​</a></h1><blockquote><p>本章是全白皮书的&quot;概念底座&quot;。不涉及任何操作，只讲清楚一件事：<strong>当你命令我干活时，背后到底发生了什么？</strong> 读懂这一章，你会从&quot;会用 AI&quot;进化到&quot;理解 AI&quot;——知道它强在哪、弱在哪、为什么会说错、怎样才能让它更可靠。</p></blockquote><h2 id="_1-先看全景-一次-ai-任务里发生了什么" tabindex="-1">1. 先看全景：一次 AI 任务里发生了什么 <a class="header-anchor" href="#_1-先看全景-一次-ai-任务里发生了什么" aria-label="Permalink to &quot;1. 先看全景：一次 AI 任务里发生了什么&quot;">​</a></h2><p>当我执行你的任务时，背后其实是一套流水线在协同工作：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的话 → 大语言模型理解（LLM）→ 分解成步骤（Agent）</span></span>
<span class="line"><span>       → 调用工具执行（Tool）→ 读取资料（RAG/记忆）</span></span>
<span class="line"><span>       → 按方法做事（Skill）→ 返回结果给你</span></span></code></pre></div><p>每个名词都是这套流水线上的一个齿轮。下面逐个拆开。</p><h2 id="_2-llm-会-接话-的预测引擎" tabindex="-1">2. LLM：会&quot;接话&quot;的预测引擎 <a class="header-anchor" href="#_2-llm-会-接话-的预测引擎" aria-label="Permalink to &quot;2. LLM：会&quot;接话&quot;的预测引擎&quot;">​</a></h2><p><strong>LLM（Large Language Model，大语言模型）</strong> 是我大脑的核心，一个经过海量文本训练、擅长&quot;根据上下文预测下一个内容&quot;的模型。</p><h3 id="_2-1-它擅长什么" tabindex="-1">2.1 它擅长什么 <a class="header-anchor" href="#_2-1-它擅长什么" aria-label="Permalink to &quot;2.1 它擅长什么&quot;">​</a></h3><ul><li>理解自然语言（中文、英文、代码都能读）；</li><li>生成连贯、有条理的文本（写文档、写代码、总结）；</li><li>推理和规划（拆步骤、做比较、找逻辑）。</li></ul><h3 id="_2-2-它不天然保证什么" tabindex="-1">2.2 它不天然保证什么 <a class="header-anchor" href="#_2-2-它不天然保证什么" aria-label="Permalink to &quot;2.2 它不天然保证什么&quot;">​</a></h3><table tabindex="0"><thead><tr><th>不保证</th><th>说明</th><th>例</th></tr></thead><tbody><tr><td>事实准确</td><td>它擅长&quot;像那么回事&quot;，不擅长&quot;确实如此&quot;</td><td>可能一本正经说错数据</td></tr><tr><td>逻辑完备</td><td>长链条推理会丢步骤</td><td>10 步逻辑可能漏 1 步</td></tr><tr><td>立场中立</td><td>受训练数据和你的引导影响</td><td>会顺着你的暗示说</td></tr></tbody></table><h3 id="_2-3-为什么会有-幻觉" tabindex="-1">2.3 为什么会有&quot;幻觉&quot; <a class="header-anchor" href="#_2-3-为什么会有-幻觉" aria-label="Permalink to &quot;2.3 为什么会有&quot;幻觉&quot;&quot;">​</a></h3><p>LLM 的机制是&quot;预测最可能的下一句&quot;，不是&quot;查证事实&quot;。当它不知道答案时，<strong>最自然的做法是&quot;编一个看起来对的&quot;</strong>——这就是幻觉。</p><p><strong>降低幻觉的四个办法：</strong></p><table tabindex="0"><thead><tr><th>办法</th><th>原理</th><th>例子</th></tr></thead><tbody><tr><td>给资料</td><td>让它&quot;读着答&quot;而不是&quot;凭记忆答&quot;</td><td>把文档给它读</td></tr><tr><td>要引用</td><td>强制它给出处</td><td>&quot;数据必须引用你读的文件&quot;</td></tr><tr><td>拆小步</td><td>长推理切成短推理</td><td>先分析再下结论</td></tr><tr><td>交叉验证</td><td>多个来源/多问一遍</td><td>让它复述+自查</td></tr></tbody></table><h2 id="_3-token-与上下文窗口-ai-的-注意力" tabindex="-1">3. Token 与上下文窗口：AI 的&quot;注意力&quot; <a class="header-anchor" href="#_3-token-与上下文窗口-ai-的-注意力" aria-label="Permalink to &quot;3. Token 与上下文窗口：AI 的&quot;注意力&quot;&quot;">​</a></h2><h3 id="_3-1-token-是什么" tabindex="-1">3.1 Token 是什么 <a class="header-anchor" href="#_3-1-token-是什么" aria-label="Permalink to &quot;3.1 Token 是什么&quot;">​</a></h3><p>模型处理文本的最小单位，<strong>一个中文词通常约等于 1~2 个 token</strong>。你发给我的所有内容（包括我读的文件、写的结果）都会换算成 token 来消耗&quot;脑力&quot;。</p><h3 id="_3-2-上下文窗口-一次能-记住-多少" tabindex="-1">3.2 上下文窗口：一次能&quot;记住&quot;多少 <a class="header-anchor" href="#_3-2-上下文窗口-一次能-记住-多少" aria-label="Permalink to &quot;3.2 上下文窗口：一次能&quot;记住&quot;多少&quot;">​</a></h3><p>每个模型有<strong>上下文窗口</strong>上限——一次任务里能同时看到的内容总量。超出部分，就&quot;看不过来了&quot;。</p><p><strong>这对你的实践意味着什么：</strong></p><table tabindex="0"><thead><tr><th>实践</th><th>原因</th></tr></thead><tbody><tr><td>长文档别一次全塞</td><td>会被截断/遗忘</td></tr><tr><td>关键信息放前面或明确强调</td><td>窗口中间的内容最容易被忽略</td></tr><tr><td>文件大就分段处理</td><td>别让上下文爆掉</td></tr></tbody></table><h3 id="_3-3-上下文是-资源-不是-无限内存" tabindex="-1">3.3 上下文是&quot;资源&quot;，不是&quot;无限内存&quot; <a class="header-anchor" href="#_3-3-上下文是-资源-不是-无限内存" aria-label="Permalink to &quot;3.3 上下文是&quot;资源&quot;，不是&quot;无限内存&quot;&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：&quot;读一下这本 500 页的书，然后写总结&quot;</span></span>
<span class="line"><span>我：（打开书）→ 发现超出上下文窗口 → 正确做法：</span></span>
<span class="line"><span>    分段读 → 每段提取要点 → 汇总要点成总结</span></span></code></pre></div><p><strong>记住：我是&quot;分段工作&quot;的，不是&quot;全书速记&quot;的。</strong> 这正是为什么白皮书里反复强调&quot;给输入、给文件、给路径&quot;——你给的材料，我用工具去读；读不下的，我分段读。</p><h2 id="_4-prompt-你下的-任务指令" tabindex="-1">4. Prompt：你下的&quot;任务指令&quot; <a class="header-anchor" href="#_4-prompt-你下的-任务指令" aria-label="Permalink to &quot;4. Prompt：你下的&quot;任务指令&quot;&quot;">​</a></h2><p><strong>Prompt（提示词）就是你对我说的话</strong>——任务指令。它决定了我的工作方向。</p><h3 id="_4-1-为什么同一件事-说法不同结果天差地别" tabindex="-1">4.1 为什么同一件事，说法不同结果天差地别 <a class="header-anchor" href="#_4-1-为什么同一件事-说法不同结果天差地别" aria-label="Permalink to &quot;4.1 为什么同一件事，说法不同结果天差地别&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌ &quot;弄一下这个数据&quot;</span></span>
<span class="line"><span>✅ &quot;阅读 data/sales.csv，按渠道和月份汇总销售额，输出表格，并指出异常&quot;</span></span></code></pre></div><p><strong>Prompt 质量 = 信息完整度。</strong> 你给的约束越多（目标/输入/格式/验收），我猜的成分越少。</p><h3 id="_4-2-好-prompt-的六个要素" tabindex="-1">4.2 好 Prompt 的六个要素 <a class="header-anchor" href="#_4-2-好-prompt-的六个要素" aria-label="Permalink to &quot;4.2 好 Prompt 的六个要素&quot;">​</a></h3><table tabindex="0"><thead><tr><th>要素</th><th>问自己</th></tr></thead><tbody><tr><td>角色</td><td>我以什么身份做？（分析师？编辑？）</td></tr><tr><td>任务</td><td>到底要什么结果？</td></tr><tr><td>输入</td><td>资料在哪？给路径/内容</td></tr><tr><td>格式</td><td>输出成什么样？（表格/清单/文档）</td></tr><tr><td>约束</td><td>有什么限制？（长度/语言/风格）</td></tr><tr><td>验收</td><td>怎么算完成？</td></tr></tbody></table><p>（完整模板见正文第 2 章与附录 A。）</p><h2 id="_5-agent-能-自主行动-的执行体" tabindex="-1">5. Agent：能&quot;自主行动&quot;的执行体 <a class="header-anchor" href="#_5-agent-能-自主行动-的执行体" aria-label="Permalink to &quot;5. Agent：能&quot;自主行动&quot;的执行体&quot;">​</a></h2><p><strong>Agent（智能体）</strong> 是 LLM 的&quot;行动版&quot;——不仅会说话，还能<strong>围绕目标循环行动</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>理解目标 → 制定计划 → 调用工具执行 → 检查结果 → 调整 → 继续</span></span></code></pre></div><h3 id="_5-1-agent-与普通聊天的区别" tabindex="-1">5.1 Agent 与普通聊天的区别 <a class="header-anchor" href="#_5-1-agent-与普通聊天的区别" aria-label="Permalink to &quot;5.1 Agent 与普通聊天的区别&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>普通聊天</th><th>Agent</th></tr></thead><tbody><tr><td>输出</td><td>文字建议</td><td>实际动作</td></tr><tr><td>循环</td><td>一问一答</td><td>计划→执行→检查→调整</td></tr><tr><td>工具</td><td>无</td><td>读写文件、执行命令</td></tr><tr><td>例子</td><td>&quot;你应该整理这个目录&quot;</td><td>&quot;我已经把目录整理好了&quot;</td></tr></tbody></table><h3 id="_5-2-agent-的核心循环" tabindex="-1">5.2 Agent 的核心循环 <a class="header-anchor" href="#_5-2-agent-的核心循环" aria-label="Permalink to &quot;5.2 Agent 的核心循环&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标 → 计划 → 行动（调工具）→ 观察结果 → 反思 → 下一轮行动</span></span></code></pre></div><p>这个循环就是我在白皮书第 1 章讲的&quot;五步协作循环&quot;的技术本质。<strong>你看到的&quot;我干活&quot;，就是这个循环在高速运转。</strong></p><h3 id="_5-3-agent-的局限" tabindex="-1">5.3 Agent 的局限 <a class="header-anchor" href="#_5-3-agent-的局限" aria-label="Permalink to &quot;5.3 Agent 的局限&quot;">​</a></h3><ul><li><strong>过度自信</strong>：会高估自己完成得有多好；</li><li><strong>目标偏离</strong>：长期任务会慢慢跑偏（所以要中间检查）；</li><li><strong>上下文有限</strong>：记住的东西随长度衰减（所以要留档、要记忆）。</li></ul><h2 id="_6-tool-让-ai-真的能-动手" tabindex="-1">6. Tool：让 AI 真的能&quot;动手&quot; <a class="header-anchor" href="#_6-tool-让-ai-真的能-动手" aria-label="Permalink to &quot;6. Tool：让 AI 真的能&quot;动手&quot;&quot;">​</a></h2><p><strong>Tool（工具）</strong> 是 Agent 的&quot;手和脚&quot;——读写文件、执行命令、搜索内容、运行脚本的能力。没有工具，Agent 只能&quot;说&quot;；有了工具，Agent 能&quot;做&quot;。</p><h3 id="_6-1-每个工具都要问的五件事" tabindex="-1">6.1 每个工具都要问的五件事 <a class="header-anchor" href="#_6-1-每个工具都要问的五件事" aria-label="Permalink to &quot;6.1 每个工具都要问的五件事&quot;">​</a></h3><p>一个合格的工具，应该回答：</p><ol><li>它干什么？（功能）</li><li>什么时候用？（触发条件）</li><li>输入是什么？（参数）</li><li>输出是什么？（结果）</li><li>边界在哪？（不能干什么/有什么风险）</li></ol><p>（我身上的工具清单，见正文第 3 章。）</p><h3 id="_6-2-工具为什么重要" tabindex="-1">6.2 工具为什么重要 <a class="header-anchor" href="#_6-2-工具为什么重要" aria-label="Permalink to &quot;6.2 工具为什么重要&quot;">​</a></h3><p><strong>工具是 AI 从&quot;建议者&quot;到&quot;执行者&quot;的分水岭。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>没有工具：AI 说&quot;你应该用 Python 写个脚本&quot;</span></span>
<span class="line"><span>有工具：  AI 已经用 Python 把脚本写好了，还跑通了</span></span></code></pre></div><h2 id="_7-skill-封装-专业工作法" tabindex="-1">7. Skill：封装&quot;专业工作法&quot; <a class="header-anchor" href="#_7-skill-封装-专业工作法" aria-label="Permalink to &quot;7. Skill：封装&quot;专业工作法&quot;&quot;">​</a></h2><p><strong>Skill（技能）</strong> 是把&quot;做一件事的最佳实践&quot;封装成可调用的方法——不仅会做，而且按<strong>规定的好方法</strong>做。</p><h3 id="_7-1-skill-与普通指令的区别" tabindex="-1">7.1 Skill 与普通指令的区别 <a class="header-anchor" href="#_7-1-skill-与普通指令的区别" aria-label="Permalink to &quot;7.1 Skill 与普通指令的区别&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>普通指令：每次都要重新交代怎么做</span></span>
<span class="line"><span>Skill：一句话触发，自动按最佳实践执行</span></span></code></pre></div><h3 id="_7-2-skill-的标准结构" tabindex="-1">7.2 Skill 的标准结构 <a class="header-anchor" href="#_7-2-skill-的标准结构" aria-label="Permalink to &quot;7.2 Skill 的标准结构&quot;">​</a></h3><ul><li><strong>用途</strong>：什么时候用它；</li><li><strong>触发</strong>：说什么话会触发；</li><li><strong>步骤</strong>：按顺序的执行动作；</li><li><strong>边界</strong>：什么情况下不能用。</li></ul><p>（如何打造自己的 Skill，见正文第 17 章。）</p><h2 id="_8-mcp-ai-世界的-标准插座" tabindex="-1">8. MCP：AI 世界的&quot;标准插座&quot; <a class="header-anchor" href="#_8-mcp-ai-世界的-标准插座" aria-label="Permalink to &quot;8. MCP：AI 世界的&quot;标准插座&quot;&quot;">​</a></h2><p><strong>MCP（Model Context Protocol，模型上下文协议）</strong> 是让 AI 与外部系统连接的<strong>标准化接口</strong>——好比电脑的 USB 接口：不管什么设备，只要支持 USB 标准，插上就能用。</p><h3 id="_8-1-mcp-解决什么问题" tabindex="-1">8.1 MCP 解决什么问题 <a class="header-anchor" href="#_8-1-mcp-解决什么问题" aria-label="Permalink to &quot;8.1 MCP 解决什么问题&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>没有 MCP：每个工具都要单独定制连接方式，麻烦、易错</span></span>
<span class="line"><span>有 MCP：统一的接口标准，工具即插即用</span></span></code></pre></div><h3 id="_8-2-mcp-与-api-的关系" tabindex="-1">8.2 MCP 与 API 的关系 <a class="header-anchor" href="#_8-2-mcp-与-api-的关系" aria-label="Permalink to &quot;8.2 MCP 与 API 的关系&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>API：一种连接方式（A 系统的接口）</span></span>
<span class="line"><span>MCP：统一了&quot;AI 怎么发现、怎么调用&quot;这些接口的标准</span></span></code></pre></div><p><strong>类比：API 是插座，MCP 是&quot;统一的插座标准&quot;。</strong></p><h2 id="_9-rag-与记忆-ai-的-外挂资料库" tabindex="-1">9. RAG 与记忆：AI 的&quot;外挂资料库&quot; <a class="header-anchor" href="#_9-rag-与记忆-ai-的-外挂资料库" aria-label="Permalink to &quot;9. RAG 与记忆：AI 的&quot;外挂资料库&quot;&quot;">​</a></h2><h3 id="_9-1-为什么需要-外挂" tabindex="-1">9.1 为什么需要&quot;外挂&quot; <a class="header-anchor" href="#_9-1-为什么需要-外挂" aria-label="Permalink to &quot;9.1 为什么需要&quot;外挂&quot;&quot;">​</a></h3><p>LLM 的训练数据有截止时间，也不包含你的私有资料。所以要让 AI 了解&quot;你的世界&quot;，需要<strong>检索增强生成（RAG，Retrieval-Augmented Generation）</strong>：先检索相关资料，再基于资料回答。</p><h3 id="_9-2-rag-的工作方式" tabindex="-1">9.2 RAG 的工作方式 <a class="header-anchor" href="#_9-2-rag-的工作方式" aria-label="Permalink to &quot;9.2 RAG 的工作方式&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的问题 → 检索相关资料（从你的文档/知识库）→ 把资料+问题一起给 LLM → 基于资料回答</span></span></code></pre></div><p><strong>效果：AI 不再&quot;凭记忆瞎说&quot;，而是&quot;读了你的资料再说话&quot;</strong>——这就是我读你给的文件、搜索你的代码库时在做的事。</p><h3 id="_9-3-记忆-vs-rag" tabindex="-1">9.3 记忆 vs RAG <a class="header-anchor" href="#_9-3-记忆-vs-rag" aria-label="Permalink to &quot;9.3 记忆 vs RAG&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>RAG（检索增强）</th><th>记忆（Memory）</th></tr></thead><tbody><tr><td>存什么</td><td>你的文档、知识库</td><td>你的偏好、决策、上下文</td></tr><tr><td>作用</td><td>回答问题时有依据</td><td>协作时懂你</td></tr><tr><td>例子</td><td>&quot;根据项目文档回答……&quot;</td><td>&quot;用户偏好中文简洁&quot;</td></tr></tbody></table><p><strong>两者结合：RAG 让我&quot;知道得多&quot;，记忆让我&quot;懂你深&quot;。</strong></p><h2 id="_10-workflow-与-agent-两条不同的路" tabindex="-1">10. Workflow 与 Agent：两条不同的路 <a class="header-anchor" href="#_10-workflow-与-agent-两条不同的路" aria-label="Permalink to &quot;10. Workflow 与 Agent：两条不同的路&quot;">​</a></h2><p>这是最容易混淆的一对概念：</p><h3 id="_10-1-workflow-预定义的流水线" tabindex="-1">10.1 Workflow：预定义的流水线 <a class="header-anchor" href="#_10-1-workflow-预定义的流水线" aria-label="Permalink to &quot;10.1 Workflow：预定义的流水线&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>步骤写死：A → B → C → D（每一步是什么都提前定好）</span></span>
<span class="line"><span>特点：可预测、稳定、适合流程固定的任务</span></span></code></pre></div><h3 id="_10-2-agent-自主决策的执行体" tabindex="-1">10.2 Agent：自主决策的执行体 <a class="header-anchor" href="#_10-2-agent-自主决策的执行体" aria-label="Permalink to &quot;10.2 Agent：自主决策的执行体&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI 自己决定：先做什么、后做什么、怎么调整</span></span>
<span class="line"><span>特点：灵活、适应变化，但结果不那么可预测</span></span></code></pre></div><h3 id="_10-3-对比表" tabindex="-1">10.3 对比表 <a class="header-anchor" href="#_10-3-对比表" aria-label="Permalink to &quot;10.3 对比表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Workflow</th><th>Agent</th></tr></thead><tbody><tr><td>步骤</td><td>预先定义</td><td>自主决定</td></tr><tr><td>可预测性</td><td>高</td><td>低</td></tr><tr><td>灵活性</td><td>低</td><td>高</td></tr><tr><td>适合</td><td>流程固定、重复任务</td><td>复杂多变、需要判断</td></tr><tr><td>类比</td><td>工厂流水线</td><td>独立顾问</td></tr></tbody></table><h3 id="_10-4-何时用哪个" tabindex="-1">10.4 何时用哪个 <a class="header-anchor" href="#_10-4-何时用哪个" aria-label="Permalink to &quot;10.4 何时用哪个&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>流程固定、重复执行 → Workflow（第 15 章自动化）</span></span>
<span class="line"><span>复杂多变、需要判断 → Agent（第 18 章多 Agent 系统）</span></span>
<span class="line"><span>最佳实践：Workflow 负责固定环节，Agent 负责判断环节</span></span></code></pre></div><h2 id="_11-一张图总结-ai-工作系统的全貌" tabindex="-1">11. 一张图总结：AI 工作系统的全貌 <a class="header-anchor" href="#_11-一张图总结-ai-工作系统的全貌" aria-label="Permalink to &quot;11. 一张图总结：AI 工作系统的全貌&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│  你（提出目标，检查结果）                  │</span></span>
<span class="line"><span>│        ↓  Prompt（任务指令）              │</span></span>
<span class="line"><span>│  ┌── LLM（理解与生成的大脑）─────────┐    │</span></span>
<span class="line"><span>│  │    ↓ 目标理解                       │    │</span></span>
<span class="line"><span>│  │  Agent（自主行动的执行体）          │    │</span></span>
<span class="line"><span>│  │    ↓ 循环：计划→行动→检查→调整      │    │</span></span>
<span class="line"><span>│  │  Tool（手和脚：读写/命令/搜索）      │    │</span></span>
<span class="line"><span>│  │  Skill（专业方法：按最佳实践做）      │    │</span></span>
<span class="line"><span>│  │  RAG/记忆（外挂资料：懂你+有依据）   │    │</span></span>
<span class="line"><span>│  └─────────────────────────────────────┘    │</span></span>
<span class="line"><span>│        ↓  MCP（标准接口连接外部系统）        │</span></span>
<span class="line"><span>│  外部世界（文件、命令、服务、团队）           │</span></span>
<span class="line"><span>└─────────────────────────────────────────┘</span></span></code></pre></div><h2 id="_12-这些概念如何对应你的日常" tabindex="-1">12. 这些概念如何对应你的日常 <a class="header-anchor" href="#_12-这些概念如何对应你的日常" aria-label="Permalink to &quot;12. 这些概念如何对应你的日常&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你做的事</th><th>背后的概念</th><th>对应章节</th></tr></thead><tbody><tr><td>把需求讲清楚</td><td>Prompt 质量</td><td>第 2 章</td></tr><tr><td>我读你的文件</td><td>RAG</td><td>第 3 章</td></tr><tr><td>我用工具干活</td><td>Tool + Agent</td><td>第 3 章</td></tr><tr><td>调用专业技能</td><td>Skill</td><td>第 5、17 章</td></tr><tr><td>我记住你的偏好</td><td>记忆系统</td><td>第 6、20 章</td></tr><tr><td>自动跑流程</td><td>Workflow</td><td>第 15 章</td></tr><tr><td>开 AI 团队</td><td>多 Agent 系统</td><td>第 8、18 章</td></tr></tbody></table><h2 id="_13-阅读建议" tabindex="-1">13. 阅读建议 <a class="header-anchor" href="#_13-阅读建议" aria-label="Permalink to &quot;13. 阅读建议&quot;">​</a></h2><ul><li><strong>不打算深究原理</strong>：记住三句话就够了——① LLM 会&quot;像那么回事&quot;地说，不一定准；② 给资料、要引用、拆小步，能显著减少幻觉；③ 我干活靠的是&quot;工具+方法+资料&quot;，所以你要给我输入和验收标准。</li><li><strong>想彻底搞懂</strong>：按顺序重读第 2、3、5、7 节，再回到正文边用边理解。</li><li><strong>以后遇到新概念</strong>：随时问我，我可以结合你的场景解释。</li></ul><hr><blockquote><p>课外阅读的定位：<strong>&quot;理解层&quot;的内容，不需要记住，需要建立直觉。</strong> 当你看到&quot;幻觉&quot;&quot;上下文&quot;&quot;Agent&quot;这些词不再发怵，这一章的目的就达到了。</p></blockquote>`,94)])])}const q=a(n,[["render",d]]);export{c as __pageData,q as default};
